#include "JusticeCaseRuntime.hpp"
#include <algorithm>
#include <cmath>
namespace elysium::fortress {bool JusticeCaseRuntime::addCase(JusticeCase c,std::string&w){if(!c.id||!c.incident){w="invalid case";return false;}return cases_.emplace(c.id,std::move(c)).second;}bool JusticeCaseRuntime::addEvidence(Evidence e,std::string&w){if(!e.id||!e.type){w="invalid evidence";return false;}e.confidence=std::clamp(std::isfinite(e.confidence)?e.confidence:0.0,0.0,1.0);return evidence_.emplace(e.id,e).second;}bool JusticeCaseRuntime::attach(StableId c,StableId e,std::string&w){auto ci=cases_.find(c);if(ci==cases_.end()||!evidence_.count(e)){w="unknown case/evidence";return false;}ci->second.evidence.push_back(e);ci->second.status=CaseStatus::Investigating;return true;}std::optional<Verdict>JusticeCaseRuntime::adjudicate(StableId id,double t,ContentId a,std::string&w){auto i=cases_.find(id);if(i==cases_.end()){w="unknown case";return std::nullopt;}double sum=0;std::size_t n=0;for(auto e:i->second.evidence){auto x=evidence_.find(e);if(x!=evidence_.end()&&x->second.visible){sum+=x->second.confidence;++n;}}double c=n?sum/n:0;if(!n){w="insufficient evidence";return std::nullopt;}bool g=c>=std::clamp(t,0.0,1.0);i->second.status=CaseStatus::Resolved;return Verdict{id,g,g?a:0,c};}}
